    category_code: "information_specialized",
    content_blocks: [
      text_block.call("次の表は，ある会員名簿から抽出したデータであり，会員番号は会員ごとに一意で，年齢欄の欠損は値が記録されていないことを表す。データの前処理に関する記述として最も適切でないものを，下のア～エの中から一つ選んで記号で答えなさい。"),
      {
        type: "table",
        headers: ["行", "会員番号", "登録日", "年齢"],
        rows: [
          ["1", "A017", "2026/04/01", "35"],
          ["2", "A018", "2026-04-01", "欠損"],
          ["3", "A018", "2026-04-01", "42"],
          ["4", "A019", "2026/04/02", "999"],
        ],
      },
    ],
    choices: [
      text_choice.call("ア", "年齢の欠損を999という符号で区別して保存した場合，平均年齢はその999を含む年齢欄の数値を合計し，行数で割って求める。", true),
      text_choice.call("イ", "登録日「2026/04/01」と「2026-04-01」は同じ年月日を表すので，日付型として読み取れる共通の形式にそろえる。"),
      text_choice.call("ウ", "会員番号A018には年齢の欠損と42が記録されているため，重複の解消には，同一会員であることに加え，項目の食い違いや更新履歴を確認する。"),
      text_choice.call("エ", "年齢999は欠損を表す符号として使われることもあるため，この名簿での符号の定義を確認し，欠損符号であれば年齢の観測値と区別する。"),
    ],
    explanation_blocks: [
      text_block.call("アが最も適切ではありません。999を欠損符号として保存することと，999歳という観測値として平均に用いることは異なります。欠損符号は実際の年齢ではないため，数値として平均の計算に混ぜてはいけません。欠損の理由や分析目的に応じて，欠損値を除外する，妥当な方法で補完するなどの処理を検討し，行った処理を明記します。イは，同じ日付を表す表記を共通の形式にする適切な処理です。ウは，会員番号の重複だけで一方を削除せず，食い違う項目や更新履歴を調べる適切な対応です。エは，元からある999を直ちに年齢として扱うのではなく，符号の意味を確認して観測値と区別するため適切です。"),
    ],
    source_text: "文部科学省『高等学校情報科「情報Ⅰ」教員研修用教材（本編）』第4章 学習22（1）・欠測値の処理・本文185頁 | https://www.mext.go.jp/content/20200722-mxt_jogai02-100013300_006.pdf#page=33\n文部科学省『高等学校情報科「情報Ⅱ」教員研修用教材（本編）』第3章 学習12「大量のデータの収集と整理・整形」2「収集したデータの整理」・本文119〜120頁 | https://www.mext.go.jp/content/20200702-mxt_jogai01-000007843_004.pdf#page=15",
  },
]

unless questions.map { |question| question.fetch(:question_number) } == (1..20).to_a
  raise "模擬試験8には問1から問20を順番に登録してください"
end

questions.each do |question|
  choices = question.fetch(:choices)
  unless choices.size == 4 && choices.count { |choice| choice.fetch(:correct) } == 1
    raise "模擬試験8 問#{question.fetch(:question_number)}の選択肢または正答数が不正です"
  end

  source_lines = question.fetch(:source_text).lines.map(&:strip).reject(&:empty?)
  unless source_lines.any? && source_lines.all? { |line| line.match?(/\A.+\s\|\shttps:\/\/\S+\z/) }
    raise "模擬試験8 問#{question.fetch(:question_number)}の出典リンク形式が不正です"
  end

  blank_labels = question.fetch(:content_blocks)
    .select { |block| block[:type] == "fill_in_quote" }
    .flat_map { |block| block[:text].scan(/\{\{([①②③④⑤])\}\}/).flatten }
    .uniq
  if blank_labels.any?
    valid_fill_in_choices = choices.all? do |choice|
      choice_blocks = choice.fetch(:content_blocks)
      choice_blocks.one? &&
        choice_blocks.first[:type] == "fill_in_choice" &&
        choice_blocks.first[:cells].size == blank_labels.size
    end
    unless valid_fill_in_choices
      raise "模擬試験8 問#{question.fetch(:question_number)}の空欄数と選択肢セル数が一致しません"
    end
  end
end

QuestionSeedSync.import(exam_number: 8, questions: questions, publication_status: "published")
